<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../includes/functions.php';require_admin();
function money_short($n){$n=(float)$n;if($n>=1000000)return '₱'.round($n/1000000,1).'M';if($n>=1000)return '₱'.round($n/1000,1).'k';return '₱'.(int)round($n);}
$products=(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn();$orders=(int)$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn();$customers=(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn();$sales=(float)$pdo->query("SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE order_status<>'Cancelled'")->fetchColumn();
$recent=$pdo->query('SELECT o.order_id,o.order_date,o.total_amount,o.order_status,u.full_name FROM orders o JOIN users u ON u.user_id=o.user_id ORDER BY o.order_date DESC LIMIT 8')->fetchAll();
$daily=$pdo->query("SELECT DATE(order_date) day,COALESCE(SUM(CASE WHEN order_status<>'Cancelled' THEN total_amount ELSE 0 END),0) amount FROM orders WHERE order_date>=CURDATE()-INTERVAL 6 DAY GROUP BY DATE(order_date)")->fetchAll();$salesByDay=[];foreach($daily as $d)$salesByDay[$d['day']]=(float)$d['amount'];$chart=[];for($i=6;$i>=0;$i--){$day=date('Y-m-d',strtotime("-$i days"));$chart[]=['label'=>date('D',strtotime($day)),'amount'=>$salesByDay[$day]??0];}$maxSale=max(array_column($chart,'amount'))?:1;

$weeklyRows=$pdo->query("SELECT YEARWEEK(order_date,1) wk,MIN(DATE(order_date)) week_start,SUM(CASE WHEN order_status<>'Cancelled' THEN total_amount ELSE 0 END) amount FROM orders WHERE order_date>=CURDATE()-INTERVAL 7 WEEK GROUP BY YEARWEEK(order_date,1) ORDER BY wk")->fetchAll();
$weeklyChart=[];foreach($weeklyRows as $r)$weeklyChart[]=['label'=>date('M j',strtotime($r['week_start'])),'amount'=>(float)$r['amount']];$maxWeek=max(array_column($weeklyChart,'amount')?:[0])?:1;
$monthlyRows=$pdo->query("SELECT DATE_FORMAT(order_date,'%Y-%m') ym,SUM(CASE WHEN order_status<>'Cancelled' THEN total_amount ELSE 0 END) amount FROM orders WHERE order_date>=DATE_SUB(CURDATE(),INTERVAL 5 MONTH) GROUP BY DATE_FORMAT(order_date,'%Y-%m') ORDER BY ym")->fetchAll();
$monthlyChart=[];foreach($monthlyRows as $r)$monthlyChart[]=['label'=>date('M',strtotime($r['ym'].'-01')),'amount'=>(float)$r['amount']];$maxMonth=max(array_column($monthlyChart,'amount')?:[0])?:1;

$lowStock=$pdo->query('SELECT product_id,product_name,stock_quantity,unit FROM products WHERE stock_quantity<=low_stock_threshold ORDER BY stock_quantity ASC,product_name LIMIT 8')->fetchAll();
$attention = [
 'Pending orders to confirm' => [(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE order_status='Pending'")->fetchColumn(), 'orders.php?status=Pending', 'Confirm orders'],
 'Online payments to verify' => [(int)$pdo->query("SELECT COUNT(*) FROM payments WHERE payment_method='Online Payment' AND payment_status='Pending'")->fetchColumn(), 'orders.php', 'Verify payments'],
 'Orders waiting for a driver' => [(int)$pdo->query("SELECT COUNT(*) FROM orders o WHERE o.order_status IN ('Preparing','Ready for Delivery') AND NOT EXISTS (SELECT 1 FROM deliveries d WHERE d.order_id=o.order_id AND d.status IN ('Assigned','Out for Delivery'))")->fetchColumn(), 'deliveries.php?tab=assign', 'Assign drivers'],
 'Deliveries today' => [(int)$pdo->query("SELECT COUNT(*) FROM deliveries WHERE scheduled_date=CURDATE() AND status IN ('Assigned','Out for Delivery')")->fetchColumn(), 'deliveries.php?tab=assigned', 'View today'],
 'Overdue deliveries' => [(int)$pdo->query("SELECT COUNT(*) FROM deliveries WHERE scheduled_date<CURDATE() AND status IN ('Assigned','Out for Delivery')")->fetchColumn(), 'deliveries.php?tab=assigned', 'Review overdue'],
 'Low-stock products' => [(int)$pdo->query('SELECT COUNT(*) FROM products WHERE stock_quantity<=low_stock_threshold')->fetchColumn(), 'inventory.php', 'Review stock']
];
$cronLast=$pdo->query("SELECT setting_value FROM buildsmart_settings WHERE setting_key='cron_last_run'")->fetchColumn();
$cronStale=!$cronLast || (time()-strtotime((string)$cronLast))>6*3600;
$statusRows=$pdo->query('SELECT order_status,COUNT(*) total FROM orders GROUP BY order_status')->fetchAll();$statusCounts=[];foreach($statusRows as $r)$statusCounts[$r['order_status']]=(int)$r['total'];
$pageTitle='Admin Dashboard';require __DIR__.'/../includes/header.php';require __DIR__.'/nav.php';
?>
<div class="page-head"><div><h1>Administrator Dashboard</h1><p class="muted">Overview of BuildSmart store activity.</p></div><a class="btn btn-outline" href="<?=BASE_URL?>/admin/reports.php">View sales analytics</a></div>
<?php if($cronStale): ?><div class="alert alert-error" role="alert"><b>Scheduled cleanup has not run<?= $cronLast ? ' since '.e($cronLast) : ' yet' ?>.</b> Unpaid orders keep their reserved stock until <code>cron/release_stale_orders.php</code> runs. See docs/HOW_TO_RUN.txt for the scheduler setup.</div><?php endif; ?>
<section class="needs-attention" aria-labelledby="attention-title"><div class="attention-heading"><div><h2 id="attention-title">Needs attention</h2><p class="muted small">Items that may need an administrator action.</p></div></div><div class="attention-grid"><a class="attention-card" href="<?= BASE_URL ?>/admin/<?= e($attention['Pending orders to confirm'][1]) ?>"><span>Pending orders to confirm</span><strong><?= (int)$attention['Pending orders to confirm'][0] ?></strong><small>Confirm orders →</small></a><a class="attention-card" href="<?= BASE_URL ?>/admin/<?= e($attention['Online payments to verify'][1]) ?>"><span>Online payments to verify</span><strong><?= (int)$attention['Online payments to verify'][0] ?></strong><small>Verify payments →</small></a><a class="attention-card" href="<?= BASE_URL ?>/admin/<?= e($attention['Orders waiting for a driver'][1]) ?>"><span>Orders waiting for a driver</span><strong><?= (int)$attention['Orders waiting for a driver'][0] ?></strong><small>Assign drivers →</small></a><a class="attention-card" href="<?= BASE_URL ?>/admin/<?= e($attention['Deliveries today'][1]) ?>"><span>Deliveries today</span><strong><?= (int)$attention['Deliveries today'][0] ?></strong><small>View today →</small></a><a class="attention-card" href="<?= BASE_URL ?>/admin/<?= e($attention['Overdue deliveries'][1]) ?>"><span>Overdue deliveries</span><strong><?= (int)$attention['Overdue deliveries'][0] ?></strong><small>Review overdue →</small></a><a class="attention-card" href="<?= BASE_URL ?>/admin/<?= e($attention['Low-stock products'][1]) ?>"><span>Low-stock products</span><strong><?= (int)$attention['Low-stock products'][0] ?></strong><small>Review stock →</small></a></div></section>
<div class="stats"><div class="card stat"><span>Products</span><strong><?= $products ?></strong></div><div class="card stat"><span>Total orders</span><strong><?= $orders ?></strong></div><div class="card stat"><span>Customers</span><strong><?= $customers ?></strong></div><div class="card stat"><span>Order value</span><strong><?= money($sales) ?></strong></div></div>
<div class="admin-dashboard-grid">
 <section class="card" id="sales-analytics"><h2>Sales · Last 7 days</h2><p class="muted small">Daily order value excluding cancelled orders</p><div class="sales-bars"><?php foreach($chart as $d): ?><div class="sales-bar-col"><strong title="<?= e(money($d['amount'])) ?>"><?= money_short($d['amount']) ?></strong><div class="sales-bar-track"><span style="height:<?= max(3,(int)round($d['amount']/$maxSale*100)) ?>%"></span></div><small><?= e($d['label']) ?></small></div><?php endforeach; ?></div></section>
 <section class="card"><h2>Low stock <span class="pill pill-warn"><?= count($lowStock) ?></span></h2><?php if(!$lowStock): ?><p class="muted">No products are currently at or below their low-stock threshold.</p><?php else: ?><div class="low-stock-list"><?php foreach($lowStock as $p): ?><div><span><?= e($p['product_name']) ?></span><strong class="<?= (int)$p['stock_quantity']===0?'text-danger':'' ?>"><?= (int)$p['stock_quantity'] ?> <?= e($p['unit']) ?></strong></div><?php endforeach; ?></div><?php endif; ?><a class="btn btn-outline btn-sm" href="<?= BASE_URL ?>/admin/inventory.php">Manage inventory</a></section>
</div>
<div class="admin-dashboard-grid">
 <section class="card"><h2>Weekly Sales · Last 8 Weeks</h2><p class="muted small">Weekly order value excluding cancelled orders</p><div class="sales-bars"><?php foreach($weeklyChart as $d): ?><div class="sales-bar-col"><strong title="<?=e(money($d['amount']))?>"><?=money_short($d['amount'])?></strong><div class="sales-bar-track"><span style="height:<?=max(3,(int)round($d['amount']/$maxWeek*100))?>%"></span></div><small><?=e($d['label'])?></small></div><?php endforeach;?></div></section>
 <section class="card"><h2>Monthly Sales · Last 6 Months</h2><p class="muted small">Monthly order value excluding cancelled orders</p><div class="sales-bars"><?php foreach($monthlyChart as $d): ?><div class="sales-bar-col"><strong title="<?=e(money($d['amount']))?>"><?=money_short($d['amount'])?></strong><div class="sales-bar-track"><span style="height:<?=max(3,(int)round($d['amount']/$maxMonth*100))?>%"></span></div><small><?=e($d['label'])?></small></div><?php endforeach;?></div></section>
</div>
<section class="card status-summary"><h2>Orders by status</h2><div class="status-chips"><?php foreach(order_statuses() as $st): ?><a href="<?= BASE_URL ?>/admin/orders.php?status=<?= urlencode($st) ?>"><span class="pill <?= pill_class($st) ?>"><?= e($st) ?></span><strong><?= $statusCounts[$st]??0 ?></strong></a><?php endforeach; ?></div></section>
<div class="card"><h2>Recent Orders</h2><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Date</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $r): ?><tr><td><a href="<?= BASE_URL ?>/admin/orders.php?id=<?= $r['order_id'] ?>">#<?= $r['order_id'] ?></a></td><td><?= e($r['full_name']) ?></td><td><?= e($r['order_date']) ?></td><td><?= money($r['total_amount']) ?></td><td><span class="pill <?= pill_class($r['order_status']) ?>"><?= e($r['order_status']) ?></span></td></tr><?php endforeach; ?><?php if(!$recent): ?><tr><td colspan="5" class="muted">No orders yet.</td></tr><?php endif; ?></tbody></table></div></div>
<?php require __DIR__.'/../includes/footer.php'; ?>
